// CSD_RATIONALE_BEGIN
// Strategy for GSM-Symbolic math word problems: two-phase guided decode.
//
// Phase 0 (guidance): AppendTaskGuidance primes the model with explicit
//   step-by-step reasoning instructions and the <<int(expr)>> answer format.
//
// Phase 1 (free reasoning): Unconstrained generation for up to ~70% of the
//   token budget (prefixBudget), giving the model room to work through the
//   problem. Terminates early on EOS. We only enter this phase when we are not
//   already inside a constrained span. After the free loop we force-open one
//   constrained span via OpenConstrainedSpan (costs 1 step), so the answer
//   is always bracketed correctly.
//
// Phase 2 (constrained close): CloseSpanWithinBudget tracks the longest
//   complete parse reachable within the remaining budget and emits ">>" there.
//   This ensures parser validity and a closed answer span whenever budget
//   permits.
//
// If maxSteps == 0 the method does nothing and cost stays 0, satisfying the
//   base case of the progress postcondition.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   - Initialization: insideConstrainedOut := insideConstrained and
//     currentConstrainedOut := currentConstrained. If insideConstrained is
//     true, the method precondition provides parser.IsValidPrefix(currentConstrained).
//     If false, the implication is vacuously true.
//   - Phase 1 free loop: the loop guard requires !insideConstrainedOut, so the
//     invariant is vacuously true throughout every iteration; neither
//     insideConstrainedOut nor currentConstrainedOut changes inside the loop.
//   - OpenConstrainedSpan: the helper postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//     Concretely it sets currentConstrainedOut := [] and parser.IsValidPrefix([])
//     holds by the method precondition.
//   - CloseSpanWithinBudget: the helper postcondition provides
//     insideOut ==> parser.IsValidPrefix(currentOut), directly preserving the
//     invariant.
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   - Initialization: generated := generatedPrefix and steps := 0, so
//     |generated| == |generatedPrefix| + 0. Holds.
//   - Phase 1 loop, non-EOS branch: generated grows by 1 and steps grows by 1.
//     Bound preserved.
//   - Phase 1 loop, EOS branch (break): generated is unchanged and steps grows
//     by 1. UnconstrainedStep consumed one token-step but appended nothing
//     visible; bound is trivially preserved.
//   - OpenConstrainedSpan: appends exactly one delimiter token ("<<"), so
//     generated grows by 1 and steps grows by 1. Bound preserved.
//   - CloseSpanWithinBudget(budget = closeBudget = maxSteps - steps_before):
//     the helper ensures |generatedOut| <= |generated_before| + closeBudget.
//     We then set steps := maxSteps, so
//     |generated| <= |generatedPrefix| + steps_before + closeBudget
//              == |generatedPrefix| + steps_before + (maxSteps - steps_before)
//              == |generatedPrefix| + maxSteps == |generatedPrefix| + steps.
//     Bound preserved.
// CSD_PROOF_SKETCH_END

generated           := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  // maxSteps == 0: the first disjunct of the progress postcondition is true;
  // all other postconditions hold from the initializations above.
} else {
  helpers.AppendTaskGuidance(lm, "Solve step by step. At the very end, write the final answer ONCE as <<int(expression)>> using only: bare variable names (no braces), integers, +, -, *, /, //, %, (, ), int(). Example: <<int(n * price + base)>>. No LaTeX, no {}, no **. Only ONE <<>> at the very end of your answer.");

  var steps: nat := 0;

  // Prefix budget: ~70% of maxSteps, always leaving at least 2 steps for
  // OpenConstrainedSpan + CloseSpanWithinBudget.
  var prefixBudget: nat;
  if maxSteps <= 2 {
    prefixBudget := 0;
  } else {
    prefixBudget := (maxSteps * 70) / 100;
    if prefixBudget > maxSteps - 2 {
      prefixBudget := maxSteps - 2;
    }
  }

  // Phase 1: Free unconstrained generation for the reasoning chain.
  // Only entered when we are not already inside a constrained span.
  if !insideConstrainedOut {
    while steps < prefixBudget
      invariant steps <= prefixBudget
      invariant prefixBudget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant |generated| <= |generatedPrefix| + steps
      decreases prefixBudget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Force-open exactly one constrained span after the free reasoning prefix.
    // At this point steps <= prefixBudget <= maxSteps - 2 < maxSteps, so the
    // guard is always true when we reach here via the normal loop exit.
    if steps < maxSteps {
      var go, io, co := helpers.OpenConstrainedSpan(lm, generated);
      generated             := go;
      insideConstrainedOut  := io;
      currentConstrainedOut := co;
      steps                 := steps + 1;
    }
  }

  // Phase 2: Bring the open constrained span to a complete parse and close it
  // within the remaining budget.
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated             := cg;
    insideConstrainedOut  := ci;
    currentConstrainedOut := cc;
    steps                 := maxSteps;
  }

  cost := steps;
}
